(function(){'use strict';
const PROFILE_KEY='safariCircleProfile',POSTS_KEY='safariCirclePosts',INTERESTS_KEY='safariCircleInterests',profileForm=document.getElementById('circleProfileForm'),onboarding=document.getElementById('circleOnboarding'),main=document.getElementById('circleMain'),feed=document.getElementById('circleFeed');if(!profileForm)return;
const interests=['Big cats','Elephants','Birding','Marine life','Conservation','Safari photography','Wildlife film','Field guiding','Family safari','Overlanding','Botswana','East Africa','Southern Africa','West & Central Africa','North Africa','African islands'];
const safe=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const read=(key,fallback)=>{try{const value=JSON.parse(localStorage.getItem(key)||'null');return value??fallback}catch{return fallback}};
const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const initials=name=>String(name||'Safari Friend').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();
const getProfile=()=>read(PROFILE_KEY,null),getPosts=()=>{const posts=read(POSTS_KEY,[]);return Array.isArray(posts)?posts:[]};
function showProfile(profile){onboarding.hidden=true;main.hidden=false;document.getElementById('circleAvatar').textContent=initials(profile.name);document.getElementById('circleProfile').innerHTML=`<div class="circle-profile-mark">${safe(initials(profile.name))}</div><h2>${safe(profile.name)}</h2><span>${safe(profile.role)}</span><p>${safe(profile.bio,'No field introduction yet.')}</p><small>${safe(profile.home,'Home country not added')}</small>`;document.getElementById('circleProfileDetail').innerHTML=`<div class="circle-profile-detail"><div class="circle-profile-mark">${safe(initials(profile.name))}</div><div><p class="eyebrow dark">${safe(profile.role)}</p><h2>${safe(profile.name)}</h2><p>${safe(profile.bio,'No field introduction yet.')}</p><small>${safe(profile.home,'Home country not added')}</small></div></div>`;renderFeed()}
function editProfile(){const profile=getProfile();onboarding.hidden=false;main.hidden=true;if(profile){document.getElementById('circleName').value=profile.name||'';document.getElementById('circleRole').value=profile.role||'Safari traveller';document.getElementById('circleHome').value=profile.home||'';document.getElementById('circleBio').value=profile.bio||''}onboarding.scrollIntoView({block:'start'})}
profileForm.addEventListener('submit',event=>{event.preventDefault();const profile={name:document.getElementById('circleName').value.trim().slice(0,60),role:document.getElementById('circleRole').value,home:document.getElementById('circleHome').value.trim().slice(0,60),bio:document.getElementById('circleBio').value.trim().slice(0,240),createdAt:getProfile()?.createdAt||new Date().toISOString()};write(PROFILE_KEY,profile);showProfile(profile)});
document.getElementById('circleEditProfile').addEventListener('click',editProfile);
document.getElementById('circleDeleteData').addEventListener('click',()=>{if(!confirm('Remove your Safari Circle profile and posts from this device?'))return;localStorage.removeItem(PROFILE_KEY);localStorage.removeItem(POSTS_KEY);localStorage.removeItem(INTERESTS_KEY);main.hidden=true;profileForm.reset();onboarding.hidden=false});
document.querySelectorAll('[data-circle-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-circle-tab]').forEach(item=>item.classList.toggle('selected',item===button));document.querySelectorAll('[data-circle-panel]').forEach(panel=>panel.hidden=panel.dataset.circlePanel!==button.dataset.circleTab)}));
function processImage(file){return new Promise((resolve,reject)=>{if(!file){resolve('');return}if(file.size>8*1024*1024){reject(new Error('Choose an image smaller than 8 MB.'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('The photograph could not be read.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('The selected file is not a usable photograph.'));image.onload=()=>{const scale=Math.min(1,1280/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.8))};image.src=reader.result};reader.readAsDataURL(file)})}
document.getElementById('circlePostForm').addEventListener('submit',async event=>{event.preventDefault();const status=document.getElementById('circleFormStatus'),button=event.target.querySelector('.circle-publish');button.disabled=true;status.textContent='Preparing your field post…';try{const image=await processImage(document.getElementById('circlePostImage').files[0]),sensitive=document.getElementById('circleSensitive').checked,post={id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,author:getProfile().name,role:getProfile().role,type:document.getElementById('circlePostType').value,species:document.getElementById('circleSpecies').value.trim().slice(0,90),country:document.getElementById('circleCountry').value.trim().slice(0,60),place:sensitive?'':document.getElementById('circlePlace').value.trim().slice(0,100),locationProtected:sensitive,text:document.getElementById('circlePostText').value.trim().slice(0,1800),visibility:document.getElementById('circleVisibility').value,image,liked:false,comments:[],createdAt:new Date().toISOString()};const posts=getPosts();posts.unshift(post);write(POSTS_KEY,posts.slice(0,100));event.target.reset();document.getElementById('circleSensitive').checked=true;status.textContent='Published to your on-device Circle.';renderFeed()}catch(error){status.textContent=error.message||'The post could not be saved.'}finally{button.disabled=false}});
function postCard(post){const when=new Date(post.createdAt).toLocaleString(),place=post.locationProtected?(post.country?`${post.country} · specific location protected`:'Specific location protected'):[post.place,post.country].filter(Boolean).join(', '),comments=Array.isArray(post.comments)?post.comments:[];return `<article class="circle-post" data-circle-post="${safe(post.id)}"><header class="circle-post-head"><span class="circle-post-avatar">${safe(initials(post.author))}</span><div><strong>${safe(post.author)}</strong><small>${safe(post.role)} · ${safe(when)}</small></div><span class="circle-post-type">${safe(post.type)}</span></header><div class="circle-post-body"><p>${safe(post.text)}</p><div class="circle-post-tags">${post.species?`<span>◎ ${safe(post.species)}</span>`:''}${place?`<span>⌖ ${safe(place)}</span>`:''}<span>${post.visibility==='private'?'🔒 Only me':post.visibility==='followers'?'◉ Followers':'◎ Public'}</span></div></div>${post.image?`<img src="${post.image}" alt="Photograph shared with this field post">`:''}<div class="circle-post-actions"><button type="button" data-like-post class="${post.liked?'active':''}">${post.liked?'♥ Appreciated':'♡ Appreciate'}</button><button type="button" data-toggle-comments>▱ ${comments.length} ${comments.length===1?'comment':'comments'}</button><button type="button" data-delete-post>Remove</button></div><div class="circle-comments" hidden>${comments.map(comment=>`<p class="circle-comment"><strong>${safe(comment.author)}</strong> ${safe(comment.text)}</p>`).join('')}<form class="circle-comment-form"><input maxlength="300" required placeholder="Add a constructive comment"><button>Post</button></form></div></article>`}
function renderFeed(){const filter=document.getElementById('circleFeedFilter').value,posts=getPosts().filter(post=>filter==='all'||post.type===filter);feed.innerHTML=posts.length?posts.map(postCard).join(''):'<div class="circle-empty"><strong>Your field feed is ready.</strong><p>Share a sighting, question, photograph, film note or safari story. Nothing fictional has been added to make the community look busy.</p></div>'}
document.getElementById('circleFeedFilter').addEventListener('change',renderFeed);
feed.addEventListener('click',event=>{const card=event.target.closest('[data-circle-post]');if(!card)return;const posts=getPosts(),post=posts.find(item=>item.id===card.dataset.circlePost);if(!post)return;if(event.target.closest('[data-like-post]'))post.liked=!post.liked;else if(event.target.closest('[data-toggle-comments]')){card.querySelector('.circle-comments').hidden=!card.querySelector('.circle-comments').hidden;return}else if(event.target.closest('[data-delete-post]')){if(!confirm('Remove this post from the device?'))return;write(POSTS_KEY,posts.filter(item=>item.id!==post.id));renderFeed();return}else return;write(POSTS_KEY,posts);renderFeed()});
feed.addEventListener('submit',event=>{const form=event.target.closest('.circle-comment-form');if(!form)return;event.preventDefault();const card=form.closest('[data-circle-post]'),posts=getPosts(),post=posts.find(item=>item.id===card.dataset.circlePost),text=form.querySelector('input').value.trim();if(!post||!text)return;post.comments=Array.isArray(post.comments)?post.comments:[];post.comments.push({author:getProfile().name,text:text.slice(0,300),createdAt:new Date().toISOString()});write(POSTS_KEY,posts);renderFeed()});
const interestBox=document.getElementById('circleInterests');function renderInterests(){const followed=new Set(read(INTERESTS_KEY,[]));interestBox.innerHTML=interests.map(item=>`<button type="button" aria-pressed="${followed.has(item)}" data-circle-interest="${safe(item)}">${followed.has(item)?'✓ ':''}${safe(item)}</button>`).join('')}interestBox.addEventListener('click',event=>{const button=event.target.closest('[data-circle-interest]');if(!button)return;const followed=new Set(read(INTERESTS_KEY,[]));followed.has(button.dataset.circleInterest)?followed.delete(button.dataset.circleInterest):followed.add(button.dataset.circleInterest);write(INTERESTS_KEY,[...followed]);renderInterests()});renderInterests();
const profile=getProfile();if(profile)showProfile(profile);else{onboarding.hidden=false;main.hidden=true}
})();
